patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..1fdd532
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,63 @@
+"use strict";
+
+/*
+ * Repro for "files on a different drive are not ignored on Windows".
+ * Runs on any OS: "path"/"node:path" are swapped for path.win32 before
+ * ESLint is loaded, and cwd is the Windows path C:\Project.
+ * "ignored" here means no-undef was not reported, i.e. the file was not linted.
+ * Exit code 1 = bug reproduced.
+ */
+
+const Module = require("node:module");
+const nodePath = require("node:path");
+
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return nodePath.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+
+const { Linter, ESLint } = require(process.env.ESLINT_API || "../lib/api");
+
+const cwd = "C:\\Project";
+const code = "foo();";
+const config = { rules: { "no-undef": "error" } };
+const cases = [
+    { file: "C:\\Project\\foo.js", label: "inside cwd", expectIgnored: false },
+    { file: "C:\\Other\\foo.js", label: "outside cwd, same drive", expectIgnored: true },
+    { file: "F:\\foo.js", label: "other drive", expectIgnored: true }
+];
+
+(async () => {
+    let failed = false;
+    const report = (api, { file, label, expectIgnored }, ignored, detail) => {
+        const ok = ignored === expectIgnored;
+
+        failed ||= !ok;
+        console.log(`${ok ? "ok  " : "BUG "} ${api.padEnd(22)} ${file.padEnd(20)} (${label}): ignored=${ignored}, expected ${expectIgnored}  ${detail}`);
+    };
+
+    const linter = new Linter({ configType: "flat", cwd });
+    const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: config });
+
+    for (const c of cases) {
+        const messages = linter.verify(code, config, c.file);
+        const linterIgnored = !messages.some(m => m.ruleId === "no-undef");
+
+        report("Linter#verify", c, linterIgnored, JSON.stringify(messages.map(m => m.ruleId ?? m.message)));
+
+        report("ESLint#isPathIgnored", c, await eslint.isPathIgnored(c.file), "");
+
+        const [result] = await eslint.lintText(code, { filePath: c.file, warnIgnored: true });
+        const lintTextIgnored = !result.messages.some(m => m.ruleId === "no-undef");
+
+        report("ESLint#lintText", c, lintTextIgnored, JSON.stringify(result.messages.map(m => m.ruleId ?? m.message)));
+    }
+
+    console.log(`\npath.win32.relative(${JSON.stringify(cwd)}, "F:\\\\foo.js") = ${JSON.stringify(nodePath.win32.relative(cwd, "F:\\foo.js"))}`);
+    console.log(failed ? "\nBUG REPRODUCED" : "\nnot reproduced");
+    process.exitCode = failed ? 1 : 0;
+})();
